import{_ as t,c as r,o,ag as a}from"./chunks/framework.ARG558ZT.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/EngX_Quality/Name_all_steps_that_are_required_to_start_a_new_project,_what_kind_of_tools_do_you_suggest_to_use._What_would_you_consider_when_choosing_tech_stack,_library,_framework.md","filePath":"senior_growth/EngX_Quality/Name_all_steps_that_are_required_to_start_a_new_project,_what_kind_of_tools_do_you_suggest_to_use._What_would_you_consider_when_choosing_tech_stack,_library,_framework.md"}'),i={name:"senior_growth/EngX_Quality/Name_all_steps_that_are_required_to_start_a_new_project,_what_kind_of_tools_do_you_suggest_to_use._What_would_you_consider_when_choosing_tech_stack,_library,_framework.md"};function n(s,e,l,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h3 id="name-all-steps-that-are-required-to-start-a-new-project-what-kind-of-tools-do-you-suggest-to-use-what-would-you-consider-when-choosing-tech-stack-library-framework" tabindex="-1">Name all steps that are required to start a new project, what kind of tools do you suggest to use? What would you consider when choosing tech stack, library/framework? <a class="header-anchor" href="#name-all-steps-that-are-required-to-start-a-new-project-what-kind-of-tools-do-you-suggest-to-use-what-would-you-consider-when-choosing-tech-stack-library-framework" aria-label="Permalink to “Name all steps that are required to start a new project, what kind of tools do you suggest to use? What would you consider when choosing tech stack, library/framework?”">​</a></h3><hr><h2 id="steps-to-start-a-new-project" tabindex="-1"><strong>Steps to Start a New Project</strong> <a class="header-anchor" href="#steps-to-start-a-new-project" aria-label="Permalink to “Steps to Start a New Project”">​</a></h2><ol><li><strong>Define the Project Requirements</strong>: <ul><li>Understand the business goals.</li><li>Identify the target audience.</li><li>Define functional and non-functional requirements.</li></ul></li><li><strong>Plan the Project Scope</strong>: <ul><li>Create a project charter or roadmap.</li><li>Define deliverables, timelines, and milestones.</li></ul></li><li><strong>Set Up Version Control</strong>: <ul><li>Use version control tools like Git and host repositories on GitHub, GitLab, or Bitbucket.</li></ul></li><li><strong>Choose the Tech Stack</strong>: <ul><li>Select the appropriate languages, frameworks, and tools based on project requirements.</li></ul></li><li><strong>Establish Development Workflow</strong>: <ul><li>Define processes for code reviews, pull requests, and deployment.</li><li>Use Agile methodologies like Scrum or Kanban if applicable.</li></ul></li><li><strong>Set Up the Development Environment</strong>: <ul><li>Prepare local development tools and configurations.</li><li>Ensure a uniform setup across team members (e.g., using Docker or Vagrant).</li></ul></li><li><strong>Design the Architecture</strong>: <ul><li>Create the application&#39;s structure (e.g., monolithic, microservices, serverless).</li><li>Define API contracts, database schemas, and service integrations.</li></ul></li><li><strong>Implement CI/CD Pipeline</strong>: <ul><li>Automate build, test, and deployment processes using tools like Jenkins, CircleCI, or GitHub Actions.</li></ul></li><li><strong>Create Boilerplate Code</strong>: <ul><li>Set up the basic structure of the project (e.g., folder hierarchy, base configurations).</li><li>Include linting and formatting tools.</li></ul></li><li><strong>Setup Documentation and Communication</strong>: <ul><li>Create a README file, document the setup process, and define coding standards.</li><li>Use tools like Confluence, Notion, or Markdown files for documentation.</li></ul></li><li><strong>Start Development</strong>: <ul><li>Begin with core features and follow the planned sprints or iterations.</li></ul></li></ol><hr><h2 id="tools-to-use" tabindex="-1"><strong>Tools to Use</strong> <a class="header-anchor" href="#tools-to-use" aria-label="Permalink to “Tools to Use”">​</a></h2><ul><li><strong>Project Management</strong>: Jira, Trello, Asana</li><li><strong>Version Control</strong>: Git, GitHub, GitLab</li><li><strong>Development Environment</strong>: Visual Studio Code, JetBrains IDEs, Docker</li><li><strong>CI/CD</strong>: Jenkins, CircleCI, GitHub Actions</li><li><strong>API Development</strong>: Postman, Swagger, Insomnia</li><li><strong>Testing</strong>: Jest, Cypress, Mocha, Selenium</li><li><strong>Documentation</strong>: Notion, Confluence, Docusaurus</li><li><strong>Monitoring</strong>: New Relic, Datadog, Sentry</li><li><strong>Communication</strong>: Slack, Microsoft Teams, Zoom</li></ul><hr><h2 id="considerations-when-choosing-tech-stack-library-framework" tabindex="-1"><strong>Considerations When Choosing Tech Stack, Library/Framework</strong> <a class="header-anchor" href="#considerations-when-choosing-tech-stack-library-framework" aria-label="Permalink to “Considerations When Choosing Tech Stack, Library/Framework”">​</a></h2><ol><li><strong>Project Requirements</strong>: <ul><li>Ensure the chosen tech aligns with functional and non-functional requirements (e.g., scalability, performance).</li></ul></li><li><strong>Team Expertise</strong>: <ul><li>Consider the team&#39;s familiarity with the tools and frameworks to reduce the learning curve.</li></ul></li><li><strong>Community and Ecosystem</strong>: <ul><li>Select tools with active communities, regular updates, and rich ecosystems.</li></ul></li><li><strong>Scalability</strong>: <ul><li>Choose technologies that can handle future growth in users, data, and features.</li></ul></li><li><strong>Performance</strong>: <ul><li>Evaluate runtime performance, resource usage, and response times.</li></ul></li><li><strong>Ease of Integration</strong>: <ul><li>Ensure the stack integrates well with third-party tools and services.</li></ul></li><li><strong>Development Speed</strong>: <ul><li>Opt for frameworks/libraries that provide high-level abstractions, out-of-the-box features, and good documentation.</li></ul></li><li><strong>Security</strong>: <ul><li>Choose technologies with strong security measures and good community support for handling vulnerabilities.</li></ul></li><li><strong>License and Cost</strong>: <ul><li>Check licensing terms to avoid potential legal issues. Consider the cost of tools if using proprietary solutions.</li></ul></li><li><strong>Longevity and Trends</strong>: <ul><li>Avoid adopting technologies that may become obsolete in the near future.</li></ul></li><li><strong>Testing and Debugging</strong>: <ul><li>Ensure tools support robust testing and debugging workflows.</li></ul></li><li><strong>Cross-platform Needs</strong>: <ul><li>For front-end projects, consider frameworks like React Native or Flutter for shared codebases across platforms.</li></ul></li></ol><h2 id="worked-project-slice-private-course-catalogue" tabindex="-1">Worked project slice: private course catalogue <a class="header-anchor" href="#worked-project-slice-private-course-catalogue" aria-label="Permalink to “Worked project slice: private course catalogue”">​</a></h2><p><strong>Outcome:</strong> an authenticated reader can browse their tenant&#39;s course titles in bounded pages. Begin with one vertical slice rather than a list of every possible framework. Primary choices: React/TypeScript frontend, Node24/Express5, PostgreSQL/MikroORM, one runtime validation approach and the existing test/build tooling. MongoDB, GraphQL, extra frameworks and cloud orchestration are alternatives when a requirement justifies them.</p><h3 id="proposed-adr-catalogue-01" tabindex="-1">Proposed ADR-CATALOGUE-01 <a class="header-anchor" href="#proposed-adr-catalogue-01" aria-label="Permalink to “Proposed ADR-CATALOGUE-01”">​</a></h3><p>Status: proposed for learner implementation; not an adopted team decision. Context: private data, shared frontend/backend contract and limited implementation scope. Decision: a modular single service with server-established identity, tenant-scoped queries, bounded cursor pagination and explicit public DTOs; keep transport/contracts separate from use cases and persistence. Alternative: arbitrary GraphQL projections could help several clients, but add query-cost/schema governance that this single operation does not yet need.</p><p>Microservices/microfrontends add deployment/coordination cost without a current independent-release requirement. Consequence: simple local ownership and one deployment, with an explicit repository/auth port and migration/rollback policy. Revisit when client projection needs or independent ownership measurably exceed this design.</p><p>Use <a href="./../../workbench/node-js/backend/rest-contracts.html">the actual OpenAPI workbench</a> for generated/checked response contracts, auth/errors/pagination and drift tests. Its real local HTTP checks are evidence for that fixture; real issuer/PostgreSQL/frontend/deployment integration remains a learner deliverable. A Swagger link alone is not a completed API contract.</p><h3 id="small-work-breakdown-and-uncertainty" tabindex="-1">Small work breakdown and uncertainty <a class="header-anchor" href="#small-work-breakdown-and-uncertainty" aria-label="Permalink to “Small work breakdown and uncertainty”">​</a></h3><p>The following are <strong>illustrative planning ranges</strong>, not measured completion times or commitments. Confirm actual team skills, template and dependencies before promising dates.</p><table tabindex="0"><thead><tr><th>Increment</th><th>Acceptance artifact</th><th>Initial estimate/uncertainty</th></tr></thead><tbody><tr><td>Contract and boundary fixture</td><td>Reviewed OpenAPI, positive/negative contract checks</td><td>2–4h; schema/tool familiarity</td></tr><tr><td>Identity and tenant repository</td><td>Actual verifier, scoped SQL, denied/revoked access tests</td><td>4–10h; issuer setup/driver configuration</td></tr><tr><td>Accessible React page</td><td>Query/selection/focus/error states and manual observations</td><td>4–8h; device/browser accessibility findings</td></tr><tr><td>Release/recovery slice</td><td>Immutable artifact, migration/restore/rollback evidence</td><td>4–10h; deployment permissions/environment</td></tr></tbody></table><p>These work items total14–32h of estimated hands-on work before unknown dependency wait time; they are not an assertion that an intermediate learner can finish on that schedule. Run a small spike for the highest uncertainty, update the range from evidence and record why it changed. Break each increment into reviewable changes; do not hide integration/review/repair time inside “done.”</p><h3 id="risk-register" tabindex="-1">Risk register <a class="header-anchor" href="#risk-register" aria-label="Permalink to “Risk register”">​</a></h3><table tabindex="0"><thead><tr><th>Risk</th><th>Impact/trigger</th><th>Owner and response</th><th>Evidence/revisit</th></tr></thead><tbody><tr><td>Tenant context taken from input</td><td>Private data leak</td><td>API owner: verified principal + scoped query before slicing</td><td>Cross-tenant/revoked tests before release</td></tr><tr><td>Contract/server change together</td><td>Older client breakage</td><td>Feature owner: consumer checks and semantic contract review</td><td>Deliberately broken field/status detected</td></tr><tr><td>Unknown issuer/DB setup</td><td>Estimate and startup failure</td><td>Learner/mentor: bounded spike and fail-closed startup</td><td>Actual configuration/connection checks, no invented access</td></tr><tr><td>Large responses/slow dependency</td><td>Saturation or unusable UI</td><td>Service owner: byte/page/deadline/pool bounds</td><td>Recorded workload and failure drill</td></tr><tr><td>Schema change closes rollback window</td><td>Failed release recovery</td><td>Release owner: expand/contract plus tested restore/rollback allowlist</td><td>Compatibility evidence from the release lesson</td></tr></tbody></table><p>Role labels are proposed responsibilities, not assigned real people or messages sent. Acceptance: produce the actual ADR, a revised evidence-based estimate, a current risk register, one contract-tested vertical slice and a handoff showing what is complete, failed and untested. Learner practice remains required. Official references: <a href="https://spec.openapis.org/oas/v3.1.2.html" target="_blank" rel="noreferrer">OpenAPI specification</a>, <a href="https://adr.github.io/madr/" target="_blank" rel="noreferrer">Markdown ADR format</a>; use an existing team format when available.</p>',23)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
